$ErrorActionPreference='Stop'
$taskOwn='E:/R4D/perspective/p5-worktrees/asset-artist/experiments/p5-regenerated-objects/transfer-water-dark/water/asset-artist';$taskRuntime='E:/R4D/perspective/p5-runtime/asset-artist/transfer-water-dark/water';$env:TEMP=Join-Path $taskRuntime 'temp';$env:TMP=$env:TEMP
Add-Type -AssemblyName System.Drawing
$taskTrace=Get-Content (Join-Path $taskOwn 'records/foreground-trace.mini-05.json') -Raw|ConvertFrom-Json
$taskFloor=Join-Path $taskRuntime 'raw/floor-v1.png';if((Get-FileHash $taskFloor -Algorithm SHA256).Hash.ToLowerInvariant() -ne $taskTrace.sourceTextureSha256){throw 'Floor pin differs'}
$taskBitmap=[Drawing.Bitmap]::new($taskFloor);$taskG=[Drawing.Graphics]::FromImage($taskBitmap);$taskPen=[Drawing.Pen]::new([Drawing.Color]::Magenta,2);$taskBrush=[Drawing.SolidBrush]::new([Drawing.Color]::FromArgb(78,255,0,150));$taskFont=[Drawing.Font]::new('Consolas',10);$taskPaths=[Collections.Generic.List[object]]::new()
try{
 foreach($taskRegion in $taskTrace.regions){$taskPts=[Drawing.PointF[]]@($taskRegion.rawPolygon|ForEach-Object{[Drawing.PointF]::new([single]$_[0],[single]$_[1])});$taskPath=[Drawing.Drawing2D.GraphicsPath]::new();$taskPath.AddPolygon($taskPts);$taskPaths.Add(@{id=$taskRegion.id;path=$taskPath});$taskG.FillPath($taskBrush,$taskPath);$taskG.DrawPath($taskPen,$taskPath);$taskG.DrawString($taskRegion.id.Replace('fg-',''),$taskFont,[Drawing.Brushes]::Black,$taskPts[0])}
 $taskChecks=@(foreach($taskProbe in @($taskTrace.clearProbes)+@($taskTrace.solidProbes)){$taskInside=@($taskPaths|Where-Object{$_.path.IsVisible([single]$taskProbe.raw[0],[single]$taskProbe.raw[1])}|ForEach-Object{$_.id});$taskShouldClear=$taskProbe.kind -in @('waterfall','arch-void','open-paving','open-water');$taskPass=$(if($taskShouldClear){$taskInside.Count -eq 0}else{$taskInside.Count -ge 1});$taskColor=$(if($taskPass){[Drawing.Color]::Lime}else{[Drawing.Color]::Red});$taskProbePen=[Drawing.Pen]::new($taskColor,2);$taskG.DrawEllipse($taskProbePen,([single]$taskProbe.raw[0]-4),([single]$taskProbe.raw[1]-4),8,8);$taskProbePen.Dispose();[ordered]@{raw=$taskProbe.raw;kind=$taskProbe.kind;insideIds=$taskInside;passed=$taskPass}})
 $taskBitmap.Save((Join-Path $taskRuntime 'evidence/floor-refs/foreground-trace-overlay.mini-05.png'),[Drawing.Imaging.ImageFormat]::Png)
 $taskOut=[ordered]@{diagnosticOnly=$true;sourceTextureSha256=$taskTrace.sourceTextureSha256;regionCount=$taskTrace.regions.Count;checks=$taskChecks;actualQa=$false;note='Статические выбранные probes не доказывают весь контур/динамику. Diagnostic overlay никогда не selected bitmap.'};$taskOut|ConvertTo-Json -Depth 8|Set-Content (Join-Path $taskOwn 'records/foreground-probes.mini-05.json') -Encoding utf8NoBOM
 $taskChecks|Where-Object{-not $_.passed}|ConvertTo-Json -Depth 5
 if(@($taskChecks|Where-Object{-not $_.passed}).Count -gt 0){throw 'Foreground selected probe failed'}
 [ordered]@{regions=$taskTrace.regions.Count;clearProbeCount=$taskTrace.clearProbes.Count;solidProbeCount=$taskTrace.solidProbes.Count;passed=$true}|ConvertTo-Json -Compress
}finally{foreach($taskP in $taskPaths){$taskP.path.Dispose()};$taskFont.Dispose();$taskBrush.Dispose();$taskPen.Dispose();$taskG.Dispose();$taskBitmap.Dispose()}
